#include "../boundary-kernel.cpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
using namespace showai_boundary;
static void require(bool b,const char*label){if(!b){std::fprintf(stderr,"vertex failure %s\n",label);std::abort();}}
static SABoundaryBudget limits(){SABoundaryBudget b{};b.max_commands=100;b.max_curves=64;b.max_pairs=1000;b.max_cuts=4096;b.max_edges=1024;b.max_leases=3;b.max_sources=8;b.max_paths=64;b.max_polynomial_degree=64;b.max_stored_bits=16384;b.max_polynomial_operations=50000000;b.max_limb_operations=1000000000;b.retained_bytes=b.workspace_bytes=16*1024*1024;return b;}
static void rectangle(SAInkPathCommand*out,double x){SAInkPathCommand a[5]={{SA_INK_MOVE,0,{x,0}},{SA_INK_LINE,0,{x+1,0}},{SA_INK_LINE,0,{x+1,1}},{SA_INK_LINE,0,{x,1}},{SA_INK_CLOSE,0,{}}};std::memcpy(out,a,sizeof a);}
static const Graph&graph(void*state,SABoundaryLease lease){auto*o=owner(state);require(o&&o->valid(lease),"actual source snapshot binding");return static_cast<const Owner*>(o)->slots[lease.slot].snapshot.get()->graph;}
int main(){auto b=limits();std::vector<uint64_t>state((sa_boundary_state_bytes()+7)/8),arena((b.retained_bytes+b.workspace_bytes)/8);SABoundaryPath path{};SABoundarySourceBlock sources[2]{};for(uint32_t i=0;i<2;i++){sources[i].key.words[0]=i+1;sources[i].first_command=i*5;sources[i].command_count=5;sources[i].affine[0]=sources[i].affine[3]=1;}SAInkPathCommand commands[10];rectangle(commands,0);rectangle(commands+5,3);
 require(sa_boundary_initialize(state.data(),uint32_t(state.size()*8),91,arena.data(),uint32_t(arena.size()*8),&b)==0,"real owner initialize");SABoundaryLease a{},moved{},touch{};require(sa_boundary_prepare(state.data(),nullptr,&path,1,sources,2,commands,10,&a)==0,"actual two-source capture");{
  const auto&old=graph(state.data(),a);require(old.incident_endpoint_count==old.edges.size()*2,"initial endpoint census");const auto&left=old.edges.chunk(3)->values[0];auto endpoint=vertex_certificate(old,left.va);require(endpoint.certificate.valid()&&endpoint.certificate.get()->point.valid()&&endpoint.certificate.get()->point.get()->exact(),"actual rational endpoint record");uint32_t refs=0;require(vertex_incidents(old,left.va,[&](const IncidentNode<Edge>&n){require(n.block.get()==old.edges.chunk_record(n.slot).get()&&n.epoch==old.output_epoch,"incidence authenticates actual immutable source block");refs+=n.references;return true;})&&refs==2,"two incident boundary endpoints");
  SABoundarySourceMutation change{};change.source=sources[1];change.source.first_command=0;rectangle(commands,6);require(sa_boundary_update(state.data(),&a,&change,1,commands,5,&moved)==0,"real separated tail update");const auto&next=graph(state.data(),moved);auto retained=vertex_certificate(next,left.va);require(retained.certificate.get()==endpoint.certificate.get()&&retained.certificate.get()->point.get()==endpoint.certificate.get()->point.get(),"unaffected actual certificate and point identities retained");require(next.vertex_incidence[retained.canonical].get()==old.vertex_incidence[endpoint.canonical].get(),"unaffected actual incident tree identity retained");
  rectangle(commands,1);require(sa_boundary_update(state.data(),&moved,&change,1,commands,5,&touch)==0,"real source touches retained component");const auto&joined=graph(state.data(),touch);require(joined.edges.same_chunk(3,old.edges),"left output payload remains actual same record");auto samepoint=vertex_certificate(joined,left.va);require(samepoint.certificate.valid()&&samepoint.certificate.get()->point.get()==endpoint.certificate.get()->point.get(),"join preserves old actual point authority");require(samepoint.steps<=32,"lookup bounded");bool alias=false;for(const auto&record:joined.point_aliases){const auto&x=*record.get();if(x.point.get()==endpoint.certificate.get()->point.get()){require(x.after.valid()&&x.after.get()->point.get()==x.point.get()&&(x.before_a.valid()||x.before_b.valid()),"source-issued alias carries before and actual after certificates");alias=true;}}require(alias,"actual source join emits point alias");refs=0;require(vertex_incidents(joined,left.va,[&](const IncidentNode<Edge>&n){require(n.block.get()==joined.edges.chunk_record(n.slot).get(),"joined index has actual current blocks");refs+=n.references;return true;})&&refs==2,"joined index complete without global scan");
  SABoundaryLease sentinel{1,2,3,4,5},failed=sentinel;rectangle(commands,9);require(sa_boundary_update(state.data(),&touch,&change,1,commands,5,&failed)==SA_INK_CAPACITY&&!std::memcmp(&failed,&sentinel,sizeof failed),"real inflight budget aborts whole next update");require(vertex_certificate(joined,left.va).certificate.get()==samepoint.certificate.get()&&vertex_certificate(old,left.va).certificate.get()==endpoint.certificate.get(),"failed stage preserves both actual source authorities");
 }
 require(sa_boundary_release(state.data(),a)==0&&sa_boundary_release(state.data(),moved)==0&&sa_boundary_release(state.data(),touch)==0&&sa_boundary_destroy(state.data())==0,"first source lifecycle released");
 // One actual closed cubic has both endpoint uses in the same curve block.
 require(sa_boundary_initialize(state.data(),uint32_t(state.size()*8),92,arena.data(),uint32_t(arena.size()*8),&b)==0,"loop owner");SAInkPathCommand loop[3]={{SA_INK_MOVE,0,{0,0}},{SA_INK_CUBIC,0,{1,1,-1,1,0,0}},{SA_INK_CLOSE,0,{}}};auto source=sources[0];source.command_count=3;SABoundaryLease closed{};require(sa_boundary_prepare(state.data(),nullptr,&path,1,&source,1,loop,3,&closed)==0,"actual closed loop");{
  const auto&g=graph(state.data(),closed);require(g.edges.chunk_count()==1&&g.edges.size()>0,"single actual closed-curve block");const auto&e=g.edges[0];const auto&last=g.edges[g.edges.size()-1];auto from=vertex_certificate(g,e.va),to=vertex_certificate(g,last.vb);require(from.certificate.valid()&&from.certificate.get()==to.certificate.get(),"loop actual shared point");uint32_t entries=0,references=0;require(vertex_incidents(g,e.va,[&](const IncidentNode<Edge>&n){++entries;references+=n.references;require(n.block.get()==g.edges.chunk_record(e.source).get(),"loop holds actual immutable block");return true;})&&entries==1&&references==2,"same-block endpoint multiplicity is two");
 }require(sa_boundary_release(state.data(),closed)==0&&sa_boundary_destroy(state.data())==0,"loop lifecycle");
 // An algebraic witness survives deletion/reuse of its original source slot.
 require(sa_boundary_initialize(state.data(),uint32_t(state.size()*8),93,arena.data(),uint32_t(arena.size()*8),&b)==0,"algebraic owner");SABoundaryPath clipped[2]={{0,0,{0,0}},{0,1,{0,0}}};SAInkPathCommand lens[8]={{SA_INK_MOVE,0,{0,0}},{SA_INK_QUAD,0,{.5,1,1,0}},{SA_INK_CLOSE,0,{}},{SA_INK_MOVE,0,{-1,.25}},{SA_INK_LINE,0,{2,.25}},{SA_INK_LINE,0,{2,2}},{SA_INK_LINE,0,{-1,2}},{SA_INK_CLOSE,0,{}}};sources[0].first_command=0;sources[0].command_count=3;sources[1].path_index=1;sources[1].first_command=3;sources[1].command_count=5;SABoundaryLease first{},second{};require(sa_boundary_prepare(state.data(),nullptr,clipped,2,sources,2,lens,8,&first)==0,"actual algebraic source");{
  Record<PointAuthority>authority;const auto&g=graph(state.data(),first);for(const auto&e:g.edges){auto v=vertex_certificate(g,e.va);if(v.certificate.valid()&&!v.certificate.get()->point.get()->exact()){authority=v.certificate.get()->point;break;}}require(authority.valid()&&authority.get()->algebraic.valid(),"actual retained algebraic point");const auto&original=*authority.get()->algebraic.get();auto x=evaluate(original.function.get()->x,{original.parameter.lower,original.parameter.upper});
  SABoundarySourceMutation update{};update.source=sources[0];lens[1].values[0]=1;lens[1].values[2]=2;require(sa_boundary_update(state.data(),&first,&update,1,lens,3,&second)==0,"original curve slot replaced");require(sa_boundary_release(state.data(),first)==0,"actual old source snapshot retired while witness pinned by live owner");const auto&retained=*authority.get()->algebraic.get();auto again=evaluate(retained.function.get()->x,{retained.parameter.lower,retained.parameter.upper});require(exact_equal(x.lower,again.lower)&&exact_equal(x.upper,again.upper),"strong-owned polynomial and root independent of recycled curve slot");
 }require(sa_boundary_release(state.data(),second)==0&&sa_boundary_destroy(state.data())==0,"algebraic lifecycle");std::printf("BOUNDARY_ACTUAL_VERTEX_AUTHORITY_OK retained_records aliases loop_multiplicity algebraic_lifetime failure_atomic\n");}
